{
  "name": "rf_link_loss_check",
  "confidence": "medium",
  "docstring": "Periodically checks an RF link/context for power-save link-loss, clearing its tick counter and triggering PHY/link-loss handling when due.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "rf_ctx",
    "a2": "flags",
    "a3": "arg",
    "v4": "tick_counter",
    "v5": "global_state_ptr",
    "v6": "ctx_state",
    "v9": "event_lock"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "context flags/status; bit 0x200 is cleared when the entry is inactive or no longer waiting"
    },
    {
      "offset": 108,
      "meaning": "link/entry state selector; non-zero leads to BLE connection handling"
    },
    {
      "offset": 115,
      "meaning": "per-context periodic check tick/counter"
    },
    {
      "offset": 116,
      "meaning": "BLE connection or entry index passed to ble_conn_get"
    }
  ]
}
